import{c as a,Q as r,j as o,m as t}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"Kernel编译时报错“error: out of jump/jumpc imm range”","description":"","frontmatter":{},"headers":[{"level":1,"title":"Kernel编译时报错“error: out of jump/jumpc imm range”","slug":"kernel编译时报错error-out-of-jumpjumpc-imm-range"},{"level":2,"title":"现象描述","slug":"现象描述"},{"level":2,"title":"问题根因","slug":"问题根因"},{"level":2,"title":"处理步骤","slug":"处理步骤"}],"relativePath":"guide/编程指南/附录/FAQ/Kernel编译时报错-error-out-of-jump-jumpc-imm-range.md","filePath":"guide/编程指南/附录/FAQ/Kernel编译时报错-error-out-of-jump-jumpc-imm-range.md"}'),l={name:"guide/编程指南/附录/FAQ/Kernel编译时报错-error-out-of-jump-jumpc-imm-range.md"};function i(n,e,p,m,s,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="kernel编译时报错-error-out-of-jump-jumpc-imm-range" tabindex="-1">Kernel编译时报错“error: out of jump/jumpc imm range” <a class="header-anchor" href="#kernel编译时报错-error-out-of-jump-jumpc-imm-range" aria-label="Permalink to &quot;Kernel编译时报错“error: out of jump/jumpc imm range”&quot;">​</a></h1><h2 id="现象描述" tabindex="-1">现象描述 <a class="header-anchor" href="#现象描述" aria-label="Permalink to &quot;现象描述&quot;">​</a></h2><p>使用工程化算子开发方式，基于自定义算子工程进行算子开发。编译算子时失败，报如下错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ERROR] [ascendxxxx] PowerCustom_88a695f03edfbc0af76b9eaae9e4556c error: out of jump/jumpc imm range</span></span></code></pre></div><h2 id="问题根因" tabindex="-1">问题根因 <a class="header-anchor" href="#问题根因" aria-label="Permalink to &quot;问题根因&quot;">​</a></h2><p>该编译错误的原因是算子kernel代码过大，导致在编译时跳转指令跳转的偏移值超过了限定的大小(int16_t的数据范围)，可通过添加编译选项“-mllvm -cce-aicore-jump-expand=true”通过间接跳转的方式来避免该问题，让编译器能够正常编译。</p><h2 id="处理步骤" tabindex="-1">处理步骤 <a class="header-anchor" href="#处理步骤" aria-label="Permalink to &quot;处理步骤&quot;">​</a></h2><ol><li><p>在kernel侧的CMakeLists中通过add_ops_compile_options针对报错算子添加编译选项“-mllvm -cce-aicore-jump-expand=true”，示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ops_compile_options(PowerCustom OPTIONS -mllvm -cce-aicore-jump-expand=true)</span></span></code></pre></div><p>add_ops_compile_options的具体使用方法请参考<a href="./../工程化算子开发/算子包编译/算子工程编译.html#section7321165972311">支持自定义编译选项</a>。</p></li><li><p>重新编译该算子。正常编译无报错。</p></li></ol>',8)])])}const h=a(l,[["render",i]]);export{d as __pageData,h as default};
